import json, time, urllib.request
import numpy as np, pandas as pd
P=["BTCUSDT","ETHUSDT","SOLUSDT","BNBUSDT","XRPUSDT","DOGEUSDT","NEARUSDT","ZECUSDT","PHAUSDT","REZUSDT","TREEUSDT","IOSTUSDT","ANIMEUSDT","BMTUSDT","CHIPUSDT","ERAUSDT","HAEDALUSDT","KORUBUSDT","NILUSDT","ADAUSDT","LINKUSDT","AVAXUSDT","SUIUSDT","LTCUSDT"]
def kl(sym,tf,n=330):
    u="https://data-api.binance.vision/api/v3/klines?symbol=%s&interval=%s&limit=%d"%(sym,tf,n)
    try: d=json.load(urllib.request.urlopen(u,timeout=20))
    except Exception as e: return None
    df=pd.DataFrame(d).iloc[:,:6]; df.columns=["t","o","h","l","c","v"]
    for k in "ohlcv": df[k]=df[k].astype(float)
    return df.iloc[:-1].reset_index(drop=True)
def ema(x,n): return pd.Series(x).ewm(span=n,adjust=False).mean().values
def rsi(c,n=14):
    d=np.diff(c,prepend=c[0]); u=pd.Series(np.where(d>0,d,0.)).ewm(alpha=1/n,adjust=False).mean().values; w=pd.Series(np.where(d<0,-d,0.)).ewm(alpha=1/n,adjust=False).mean().values
    return 100-100/(1+u/np.maximum(w,1e-12))
def score(df):
    c=df.c.values; e20,e50,e200=ema(c,20),ema(c,50),ema(c,200)
    return int(np.sign(c[-1]-e50[-1])+np.sign(e20[-1]-e50[-1])+np.sign(e50[-1]-e50[-4])+np.sign(e50[-1]-e200[-1]))
rows=[]
for s in P:
    r={"sym":s}; ok=True
    for tf in ("1d","4h","1h","15m"):
        df=kl(s,tf); time.sleep(0.15)
        if df is None or len(df)<210: ok=False; break
        r["s"+tf]=score(df)
        c=df.c.values; r["rsi"+tf]=round(float(rsi(c)[-1]))
        if tf in ("1h","15m"):
            pc=np.r_[c[0],c[:-1]]; tr=np.maximum(df.h.values-df.l.values,np.maximum(abs(df.h.values-pc),abs(df.l.values-pc))); atr=pd.Series(tr).ewm(alpha=1/14,adjust=False).mean().values[-1]
            r["x"+tf]=round(float((c[-1]-ema(c,20)[-1])/atr),1)
            if tf=="1h": r["atr1h%"]=round(float(atr/c[-1]*100),2)
        if tf=="1h": r["px"]=float(c[-1])
    if ok: rows.append(r)
for r in sorted(rows,key=lambda r: -(abs(r["s4h"])+abs(r["s1h"])+abs(r["s1d"]))):
    print(r["sym"],"1d",r["s1d"],"4h",r["s4h"],"1h",r["s1h"],"15m",r["s15m"],"| RSI 4h/1h/15m",r["rsi4h"],r["rsi1h"],r["rsi15m"],"| dist EMA20 1h/15m (ATR)",r["x1h"],r["x15m"],"| ATR1h%",r["atr1h%"],"px",r["px"])
EOF
